/// NL→IR Item C1 Path A: per-event typed `_event.data` inject seam.
/// Bring into scope with `use …::StaticModelHarnessInject;` to call the
/// `raise_<event>` methods on the engine.
pub trait StaticModelHarnessInject {
    /// Typed `_event.data` inject for `harness.offer`.
    /// Binds the event name and payload variant in one call (name↔type
    /// pairing cannot be constructed inconsistently).
    fn raise_harness_offer(&mut self, payload: StaticModelHarnessHarnessOfferPayload);
    /// Typed `_event.data` inject for `harness.start`.
    /// Binds the event name and payload variant in one call (name↔type
    /// pairing cannot be constructed inconsistently).
    fn raise_harness_start(&mut self, payload: StaticModelHarnessHarnessStartPayload);
}

impl StaticModelHarnessInject for ::sce_rust_runtime::Engine<StaticModelHarnessPolicy> {
    fn raise_harness_offer(&mut self, payload: StaticModelHarnessHarnessOfferPayload) {
        let data = ::sce_rust_runtime::payload_wire(format_args!("{{\"id\":{}}}", payload.id));
        self.raise_external_typed_with_data(
            StaticModelHarnessEvent::HarnessOffer,
            StaticModelHarnessPayload::HarnessOffer(payload),
            &data,
        );
    }
    fn raise_harness_start(&mut self, payload: StaticModelHarnessHarnessStartPayload) {
        let data = ::sce_rust_runtime::payload_wire(format_args!(
            "{{\"request\":{}}}",
            ::sce_rust_runtime::event_payload::quote(&payload.request)
        ));
        self.raise_external_typed_with_data(
            StaticModelHarnessEvent::HarnessStart,
            StaticModelHarnessPayload::HarnessStart(payload),
            &data,
        );
    }
}

