/// The host side of this document's typed `<invoke type="sce-host-model-generate">`s
/// (SCE Accepted Subset §2.12). Register it with
/// `register_sce_host_model_generate_invoker`.
pub trait StaticModelHarnessSceHostModelGenerateInvoker: Send + 'static {
    /// §scxml-6.4: begin `<invoke id="gen">`. `token` names this start;
    /// a host that finishes later hands it back to `complete_gen` (or
    /// `complete_host_invoke`). `Some` completes the invocation now.
    fn start_gen(
        &mut self,
        request: StaticModelHarnessGenRequest,
        token: u64,
    ) -> Option<StaticModelHarnessGenResult>;
    /// §scxml-6.4: `<invoke id="gen">`'s state exited while the start
    /// `token` names was still running. Stop it.
    fn cancel_gen(&mut self, token: u64);
}

/// Registration and typed completion for this document's typed host-run
/// invokes. Bring into scope with `use …::StaticModelHarnessHostInvokers;`.
pub trait StaticModelHarnessHostInvokers {
    /// Complete `<invoke id="gen">`'s start `token` with its record —
    /// `complete_host_invoke` with the record's JSON, so a stale or unknown
    /// token is refused the same way (`false`).
    fn complete_gen(&mut self, token: u64, result: StaticModelHarnessGenResult) -> bool;
    /// Register `invoker` as the handler for `type="sce-host-model-generate"`.
    fn register_sce_host_model_generate_invoker<I>(&mut self, invoker: I)
    where
        I: StaticModelHarnessSceHostModelGenerateInvoker;
}

impl StaticModelHarnessHostInvokers for ::sce_rust_runtime::Engine<StaticModelHarnessPolicy> {
    fn complete_gen(&mut self, token: u64, result: StaticModelHarnessGenResult) -> bool {
        self.complete_host_invoke("sce-host-model-generate", "gen", token, &result.wire())
    }
    fn register_sce_host_model_generate_invoker<I>(&mut self, mut invoker: I)
    where
        I: StaticModelHarnessSceHostModelGenerateInvoker,
    {
        self.register_invoker("sce-host-model-generate", move |event| match event {
            ::sce_rust_runtime::HostInvokeEvent::Start(request) => match request.invoke_id.as_str()
            {
                "gen" => {
                    let typed = StaticModelHarnessGenRequest {
                        prompt: ::sce_rust_runtime::request_field(&request, "prompt"),
                        answer_schema: ::sce_rust_runtime::request_field(&request, "answer_schema"),
                        max_tokens: ::sce_rust_runtime::request_field(&request, "max_tokens"),
                        temperature_milli: ::sce_rust_runtime::request_field(
                            &request,
                            "temperature_milli",
                        ),
                    };
                    invoker.start_gen(typed, request.token).map(|result| {
                        ::sce_rust_runtime::HostInvokeResponse {
                            done_data: Some(StaticModelHarnessGenResult::wire(&result)),
                            ..::sce_rust_runtime::HostInvokeResponse::default()
                        }
                    })
                }
                _ => None,
            },
            ::sce_rust_runtime::HostInvokeEvent::Cancel(cancel) => {
                match cancel.invoke_id.as_str() {
                    "gen" => {
                        invoker.cancel_gen(cancel.token);
                        None
                    }
                    _ => None,
                }
            }
        });
    }
}

