    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            StaticModelHarnessState::Accepted => "accepted",
            StaticModelHarnessState::Check => "check",
            StaticModelHarnessState::Compose => "compose",
            StaticModelHarnessState::GaveUp => "gave_up",
            StaticModelHarnessState::Generate => "generate",
            StaticModelHarnessState::Harness => "harness",
            StaticModelHarnessState::Repair => "repair",
            StaticModelHarnessState::Retry => "retry",
            StaticModelHarnessState::Waiting => "waiting",
            StaticModelHarnessState::Work => "work",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the slice `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "accepted" => Some(StaticModelHarnessState::Accepted),
            "check" => Some(StaticModelHarnessState::Check),
            "compose" => Some(StaticModelHarnessState::Compose),
            "gave_up" => Some(StaticModelHarnessState::GaveUp),
            "generate" => Some(StaticModelHarnessState::Generate),
            "harness" => Some(StaticModelHarnessState::Harness),
            "repair" => Some(StaticModelHarnessState::Repair),
            "retry" => Some(StaticModelHarnessState::Retry),
            "waiting" => Some(StaticModelHarnessState::Waiting),
            "work" => Some(StaticModelHarnessState::Work),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        StaticModelHarnessEvent::Null
    }

    // NL→IR Item C1 Path A: store the current event's typed `_event.data`
    // payload so native transition guards can read it without a script
    // engine. Called by the engine's pop loop for every dequeued event;
    // events injected without a typed payload carry the `#[default] None`
    // variant, against which the variant-specific guards simply fail.
    fn populate_event_payload(&mut self, payload: &Self::Payload) {
        self.pending_payload = payload.clone();
    }

    // NL→IR Item C1 Path A: …and when no typed payload rode with the event,
    // read that view out of the `data` every other producer fills — `<send>`
    // with `<param>`, an invoke forwarding either way, autoforward, BasicHTTP,
    // mesh. A payload that does not read as this event's schema is returned as
    // a refusal, on which the engine refuses the delivery whole and takes an
    // `error.execution` in its place (docs/adr/0086, section 4.2).
    fn lift_event_payload(
        &mut self,
        event: Self::Event,
        data: &str,
    ) -> ::core::result::Result<(), ::sce_rust_runtime::event_payload::PayloadRefusal> {
        // A typed payload already bound the view, so the producer was the inject
        // seam and there is nothing to read out of `data`.
        if self.pending_payload != StaticModelHarnessPayload::None {
            return Ok(());
        }
        match event {
            StaticModelHarnessEvent::DoneInvokeGen => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = StaticModelHarnessPayload::DoneInvokeGen(
                    StaticModelHarnessDoneInvokeGenPayload {
                        error: fields.text("error", 24)?,
                        text: fields.text("text", 4096)?,
                        constrained: fields.truth("constrained")?,
                        model: fields.text("model", 128)?,
                        prompt_tokens: fields.unsigned::<u32>("prompt_tokens")?,
                        answer_tokens: fields.unsigned::<u32>("answer_tokens")?,
                        finish: fields.text("finish", 16)?,
                    },
                );
            }
            StaticModelHarnessEvent::HarnessOffer => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = StaticModelHarnessPayload::HarnessOffer(
                    StaticModelHarnessHarnessOfferPayload {
                        id: fields.unsigned::<u32>("id")?,
                    },
                );
            }
            StaticModelHarnessEvent::HarnessStart => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = StaticModelHarnessPayload::HarnessStart(
                    StaticModelHarnessHarnessStartPayload {
                        request: fields.text("request", 512)?,
                    },
                );
            }
            _ => {}
        }
        Ok(())
    }

